package cn.zhuatech.dealer.deep;import cn.zhuatech.dealer.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/admin/dealer-ops") public class DeepAdminController{private final DeepDomainService s;public DeepAdminController(DeepDomainService s){this.s=s;}@PostMapping("/dealers/{id}/approve")ApiResponse<?> approve(@PathVariable Long id,@Valid @RequestBody DeepDomainService.ApprovalRequest r){return ApiResponse.ok(s.approve(id,r));}@PostMapping("/orders/{id}/approve")ApiResponse<?> order(@PathVariable Long id){return ApiResponse.ok(s.approveOrder(id));}@PostMapping("/rebates/{id}/settle")ApiResponse<?> settle(@PathVariable Long id,@Valid @RequestBody DeepDomainService.SettleRequest r){return ApiResponse.ok(s.settle(id,r));}}
